-- Fixed original-plan diagnostic. USD; original gross modeled-loss comparison, not a causal cutoff test.
-- Run on verified read replica; one-account cohort validated in performance.sql.
BEGIN READ ONLY; SET LOCAL statement_timeout='25s';
WITH t AS MATERIALIZED (SELECT a.*,i.cycle_id FROM accounting_transactions a JOIN intents i USING(intent_id) WHERE occurred_at>='2026-11-16' AND occurred_at<'2026-11-26'), ep AS MATERIALIZED (SELECT cycle_id,symbol,min(occurred_at) start_at,max(occurred_at) end_at,count(*) fill_count,sum(realized_pnl_micros)/1e6 pnl,sum(quantity_delta_atoms) residual FROM t GROUP BY cycle_id,symbol), p AS MATERIALIZED (SELECT e.*,s.document->'targetPlan'->'intentTargets'->0->>'side' side,s.document->'strategyDecision'->'exitPolicy'->'plans'->e.symbol plan FROM ep e JOIN autonomous_cycle_shadow_decisions s USING(cycle_id)), x AS MATERIALIZED (SELECT *,CASE WHEN side='BUY' THEN ((plan->>'estimatedTargetNetMicros')::numeric-(plan->>'acquisitionCostMicros')::numeric)/1e6 ELSE (plan->>'estimatedTargetPnlMicros')::numeric/1e6 END gain,CASE WHEN side='BUY' THEN ((plan->>'acquisitionCostMicros')::numeric-(plan->>'estimatedStopNetMicros')::numeric)/1e6 ELSE -(plan->>'estimatedStopPnlMicros')::numeric/1e6 END loss FROM p)
SELECT 'plan_summary',(start_at AT TIME ZONE 'America/New_York')::date AS session_day,side,plan->'levels'->'source'->>'setup' AS setup,count(*),sum(pnl),count(gain),count(loss),round(min(gain),4),round(max(gain),4),round(min(loss),4),round(max(loss),4),count(*)FILTER(WHERE pnl < -loss) AS beyond_modeled_loss FROM x GROUP BY session_day,side,setup ORDER BY session_day,side,setup;
WITH t AS MATERIALIZED (SELECT a.*,i.cycle_id FROM accounting_transactions a JOIN intents i USING(intent_id) WHERE occurred_at>='2026-11-24' AND occurred_at<'2026-11-26'), ep AS MATERIALIZED (SELECT cycle_id,symbol,min(occurred_at) start_at,sum(realized_pnl_micros)/1e6 pnl FROM t GROUP BY cycle_id,symbol), p AS MATERIALIZED (SELECT e.*,s.document->'targetPlan'->'intentTargets'->0->>'side' side,s.document->'strategyDecision'->'exitPolicy'->'plans'->e.symbol plan FROM ep e JOIN autonomous_cycle_shadow_decisions s USING(cycle_id)), x AS MATERIALIZED (SELECT *,CASE WHEN side='BUY' THEN ((plan->>'estimatedTargetNetMicros')::numeric-(plan->>'acquisitionCostMicros')::numeric)/1e6 ELSE (plan->>'estimatedTargetPnlMicros')::numeric/1e6 END gain,CASE WHEN side='BUY' THEN ((plan->>'acquisitionCostMicros')::numeric-(plan->>'estimatedStopNetMicros')::numeric)/1e6 ELSE -(plan->>'estimatedStopPnlMicros')::numeric/1e6 END loss FROM p), b AS (SELECT *,CASE WHEN gain/loss <.25 THEN '<0.25' WHEN gain/loss<.5 THEN '0.25-<0.5' WHEN gain/loss<1 THEN '0.5-<1' ELSE '>=1' END AS bin FROM x)
SELECT 'ratio_bins',(start_at AT TIME ZONE 'America/New_York')::date AS session_day,bin,count(*),count(*)FILTER(WHERE pnl>0),sum(pnl),round(sum(gain),4),round(sum(loss),4) FROM b GROUP BY session_day,bin ORDER BY session_day,bin;
COMMIT;
